/// How rule `atom`'s alternatives are told apart by a node's labeled children.
static _ATOM_SIGNATURES: ::fltk_ast_core::dispatch::Table = ::fltk_ast_core::dispatch::Table {
    pairs: &[
        ::fltk_ast_core::dispatch::Pair { label: "num", kind: "num" },
        ::fltk_ast_core::dispatch::Pair { label: "name", kind: "name" },
    ],
    alternatives: &[
        ::fltk_ast_core::dispatch::Alt {
            variant: 0,
            bounds: &[
                ::fltk_ast_core::dispatch::Bound { label: "num", pairs: &[0], minimum: 1, maximum: 1 },
            ],
            forbidden: &[1],
        },
        ::fltk_ast_core::dispatch::Alt {
            variant: 1,
            bounds: &[
                ::fltk_ast_core::dispatch::Bound { label: "name", pairs: &[1], minimum: 1, maximum: 1 },
            ],
            forbidden: &[0],
        },
    ],
};

/// Which alternative of rule `atom` the node's labeled children came from.
///
/// The CST does not record it, so each child is classified into the (label, kind) pair
/// it occupies and the runtime takes the first alternative accepting those counts.
fn _atom_alternative(node: &cst::Atom) -> ::std::option::Option<usize> {
    _ATOM_SIGNATURES.select(node.children().iter().map(|(label, child)| {
        let label = if matches!(label, Some(cst::AtomLabel::Num)) {
            Some("num")
        } else if matches!(label, Some(cst::AtomLabel::Name)) {
            Some("name")
        } else if label.is_some() {
            Some("")
        } else {
            None
        };
        let kind = if matches!(child, cst::AtomChild::Num(_)) {
            "num"
        } else if matches!(child, cst::AtomChild::Name(_)) {
            "name"
        } else {
            ""
        };
        (label, kind)
    }))
}

impl Atom {
    /// Convert a `atom` CST node, dispatching on the matched alternative.
    pub fn from_cst(node: &::fltk_cst_core::Shared<cst::Atom>) -> ::std::result::Result<Self, ::fltk_ast_core::AstError> {
        let (alternative, span) = {
            let cst_node = node.read();
            (_atom_alternative(&cst_node), cst_node.span().clone())
        };
        match alternative {
            Some(0) => {
                let cst_node = node.read();
                let children_num: ::std::vec::Vec<&cst::AtomChild> = cst_node
                    .children()
                    .iter()
                    .filter(|(label, _)| matches!(label, Some(cst::AtomLabel::Num)))
                    .map(|(_, child)| child)
                    .collect();
                let child = ::fltk_ast_core::one(&children_num, "atom", "num", cst_node.span())?;
                let cst::AtomChild::Num(child_node) = child else {
                    return Err(::fltk_ast_core::unexpected_child("atom", "num", cst_node.span()));
                };
                Ok(Self::Num(Num::from_cst(child_node)?))
            }
            Some(1) => {
                let cst_node = node.read();
                let children_name: ::std::vec::Vec<&cst::AtomChild> = cst_node
                    .children()
                    .iter()
                    .filter(|(label, _)| matches!(label, Some(cst::AtomLabel::Name)))
                    .map(|(_, child)| child)
                    .collect();
                let child = ::fltk_ast_core::one(&children_name, "atom", "name", cst_node.span())?;
                let cst::AtomChild::Name(child_node) = child else {
                    return Err(::fltk_ast_core::unexpected_child("atom", "name", cst_node.span()));
                };
                Ok(Self::Name(Name::from_cst(child_node)?))
            }
            _ => Err(::fltk_ast_core::AstError::new("rule \"atom\": no alternative matches the node's labeled children", span)),
        }
    }
}

